	@Test
	public void retainedSnapshotIsStableAcrossIndependentWriterAddAndRemove() throws Exception {
		openFixture(true, false);
		try (SailRepositoryConnection reader = repository.getConnection()) {
			reader.begin(IsolationLevels.SNAPSHOT);
			assertConnectionCountParity(reader, 10L);
			try (SailRepositoryConnection writer = repository.getConnection()) {
				ValueFactory vf = writer.getValueFactory();
				writer.add(vf.createIRI(EX + "new-node"), vf.createIRI(EX + "q"), vf.createLiteral("new leaf"));
			}
			assertConnectionCountParity(reader, 10L);
			assertThat(countValue(rows(ABSENT_COUNT, true, true, true))).isEqualTo(12L);
			try (SailRepositoryConnection writer = repository.getConnection()) {
				writer.remove(writer.getValueFactory().createIRI(EX + "n"), null, null);
			}
			assertConnectionCountParity(reader, 10L);
			assertThat(countValue(rows(ABSENT_COUNT, true, true, true))).isEqualTo(9L);
			reader.rollback();
		}
		reopenReady();
		assertParity(ABSENT_COUNT, true, true);
		assertThat(countValue(rows(ABSENT_COUNT, true, true, true))).isEqualTo(9L);
	}

