	private void assertConnectionCountParity(SailRepositoryConnection connection, long expected) {
		System.setProperty(NATIVE, "true");
		System.setProperty(ENABLED, "false");
		List<BindingSet> baseline = QueryResults.asList(connection.prepareTupleQuery(ABSENT_COUNT).evaluate());
		assertThat(countValue(baseline)).isEqualTo(expected);
		System.setProperty(ENABLED, "true");
		assertThat(QueryResults.asList(connection.prepareTupleQuery(ABSENT_COUNT).evaluate()))
				.containsExactlyInAnyOrderElementsOf(baseline);
		System.setProperty(NATIVE, "false");
		System.setProperty(ENABLED, "false");
		assertThat(QueryResults.asList(connection.prepareTupleQuery(ABSENT_COUNT).evaluate()))
				.containsExactlyInAnyOrderElementsOf(baseline);
	}

	private void assertParity(String query, boolean requireDomain, boolean includeInferred) {
		List<BindingSet> baseline = rows(query, true, false, includeInferred);
		assertThat(rows(query, false, false, includeInferred)).as("generic baseline: " + query)
				.containsExactlyInAnyOrderElementsOf(baseline);
		long before = ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get();
		long rowsBefore = ZeroLengthPathPlan.NODE_DOMAIN_ROWS.get();
		assertThat(rows(query, true, true, includeInferred)).as("ID-node producer: " + query)
				.containsExactlyInAnyOrderElementsOf(baseline);
		assertThat(rows(query, true, null, includeInferred)).as("default ID-node producer: " + query)
				.containsExactlyInAnyOrderElementsOf(baseline);
		if (requireDomain) {
			assertThat(ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get()).as("actual adjacency node-domain service: " + query)
					.isGreaterThan(before);
			assertThat(ZeroLengthPathPlan.NODE_DOMAIN_ROWS.get()).as("actual node rows: " + query)
					.isGreaterThan(rowsBefore);
		}
	}

	private List<BindingSet> rows(String query, boolean nativeEngine, Boolean nodeIds, boolean includeInferred) {
		System.setProperty(NATIVE, Boolean.toString(nativeEngine));
		if (nodeIds == null) {
			System.clearProperty(ENABLED);
		} else {
			System.setProperty(ENABLED, Boolean.toString(nodeIds));
		}
		try (SailRepositoryConnection connection = repository.getConnection()) {
			TupleQuery prepared = connection.prepareTupleQuery(query);
			prepared.setIncludeInferred(includeInferred);
			return QueryResults.asList(prepared.evaluate());
		}
	}

	private static long countValue(List<BindingSet> rows) {
		assertThat(rows).hasSize(1);
		return ((Literal) rows.get(0).getValue("n")).longValue();
	}

	private void openFixture(boolean adjacency, boolean legacy) throws Exception {
		this.adjacency = adjacency;
		this.legacy = legacy;
		if (legacy) {
			LmdbCompatibilityFixtures.extract("v2-empty-inline-false.zip", dataDir.toPath());
		}
		openRepository();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI a = vf.createIRI(EX + "a");
			IRI b = vf.createIRI(EX + "b");
			IRI n = vf.createIRI(EX + "n");
			IRI p = vf.createIRI(EX + "p");
			IRI q = vf.createIRI(EX + "q");
			IRI g1 = vf.createIRI(EX + "g1");
			IRI g2 = vf.createIRI(EX + "g2");
			var blank = vf.createBNode("node");
			connection.begin();
			connection.add(a, p, b);
			connection.add(a, p, b, g1);
			connection.add(a, p, a, g1);
			connection.add(b, q, vf.createLiteral("leaf"));
			connection.add(b, q, vf.createLiteral("7", XSD.INTEGER));
			connection.add(b, q, vf.createLiteral("07", XSD.INTEGER));
			connection.add(blank, q, vf.createLiteral("hi", "en"));
			connection.add(blank, q, vf.createLiteral("hi", "EN"), g2);
			connection.add(n, q, b, g2);
			connection.add(n, q, vf.createLiteral(1.5), g2);
			connection.add(n, q, vf.createLiteral("1.50", XSD.DECIMAL), g2);
			IRI ghost = vf.createIRI(EX + "dictionary-only");
			connection.add(ghost, p, ghost);
			connection.remove(ghost, p, ghost);
			connection.commit();
		}
		reopenReady();
	}

	private void openRepository() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency)
				.setInlineLiterals(!legacy);
		store = new LmdbStore(dataDir, config);
		repository = new SailRepository(store);
		repository.init();
	}

	private void reopenReady() throws InterruptedException {
		repository.shutDown();
		openRepository();
		if (adjacency) {
			assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS))
					.as(store.getDirectAdjacencyReadinessDescription())
					.isTrue();
		}
	}

